import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { GoogleAuth } from 'google-auth-library';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.GOOGLE_APPLICATION_CREDENTIALS, 'ADC names the issued service-account key file');
const credentials = JSON.parse(readFileSync(process.env.GOOGLE_APPLICATION_CREDENTIALS, 'utf8'));
assert.equal(credentials.type, 'service_account');
const scope = 'https://www.googleapis.com/auth/cloud-platform';
const auth = new GoogleAuth({ scopes: [scope] });
const client = await auth.getClient();
const { token } = await client.getAccessToken();
assert.ok(typeof token === 'string' && token.length > 0, 'the signed service-account assertion returns an access token');
writeFileSync('.google-access.json', JSON.stringify({
  token, scope, clientId: credentials.client_id, clientEmail: credentials.client_email, keyId: credentials.private_key_id,
}) + '\n', { mode: 0o600 });
await import('./readback.mjs');

