import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { OAuth2Client } from 'google-auth-library';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
const saved = JSON.parse(readFileSync('.google-access.json', 'utf8'));
const credentials = JSON.parse(readFileSync(process.env.GOOGLE_APPLICATION_CREDENTIALS, 'utf8'));
assert.equal(credentials.client_id, saved.clientId);
assert.equal(credentials.client_email, saved.clientEmail);
assert.equal(credentials.private_key_id, saved.keyId, 'resume retains the deployment service-account key');
const info = await new OAuth2Client().getTokenInfo(saved.token);
assert.equal(info.aud, saved.clientId, 'the token belongs to the issued service account');
assert.deepEqual(info.scopes, [saved.scope]);
assert.ok(Number.isFinite(info.expiry_date) && info.expiry_date > Date.now(), 'the retained token is live');
console.log(JSON.stringify({ audience: info.aud, scopes: info.scopes, retainedToken: true }));
